package secretscan_test

import (
	"fmt"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/guardana/control/internal/secretscan"
)

// benchDocument is about 16 MiB of JSON strings of lower-case letters,
// digits and spaces, generated by a fixed linear congruential sequence.
func benchDocument() []byte {
	const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789 "
	const size = 16 << 20
	var b strings.Builder
	b.Grow(size + 1024)
	b.WriteString(`{"content":[`)
	x := uint32(1)
	for b.Len() < size {
		if b.Len() > 20 {
			b.WriteByte(',')
		}
		b.WriteString(`{"type":"text","text":"`)
		for range 4000 {
			x = x*1664525 + 1013904223
			b.WriteByte(alphabet[(x>>16)%uint32(len(alphabet))])
		}
		b.WriteString(`"}`)
	}
	b.WriteString(`]}`)
	return []byte(b.String())
}

func benchSecrets() []secretscan.Secret {
	out := make([]secretscan.Secret, 0, 20)
	for i := range 20 {
		kind := secretscan.Credential
		if i%2 == 1 {
			kind = secretscan.MaybeCredential
		}
		out = append(out, secretscan.Secret{
			Key:   fmt.Sprintf("bench.secret.%d", i),
			Value: fmt.Sprintf("Absent-Value_%02d/x", i),
			Kind:  kind,
		})
	}
	return out
}

func BenchmarkScanJSON(b *testing.B) {
	doc := benchDocument()
	set, err := secretscan.New(benchSecrets())
	if err != nil {
		b.Fatalf("New: %v", err)
	}
	b.SetBytes(int64(len(doc)))
	samples := make([]time.Duration, 0, 64)
	for b.Loop() {
		start := time.Now()
		v := set.ScanJSON(doc)
		samples = append(samples, time.Since(start))
		if v.State != secretscan.Clean {
			b.Fatalf("verdict %+v, want clean", v)
		}
	}
	sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })
	at := func(p float64) float64 {
		return float64(samples[int(p*float64(len(samples)-1))].Nanoseconds())
	}
	b.ReportMetric(at(0.50), "p50-ns/op")
	b.ReportMetric(at(0.99), "p99-ns/op")
}

// adversarialSecrets is n secrets of both kinds, from one byte to 64, with
// characters that give JSON-escaped and base64 spellings; none occurs in
// the adversarial documents.
func adversarialSecrets(n int) []secretscan.Secret {
	stems := []string{"Q", "Zx/", "ZZ<é/ZY", "98765432109", "Wq+%41/Wq", "XYZ_é😀<>&/"}
	out := make([]secretscan.Secret, 0, n)
	for i := range n {
		stem := stems[i%len(stems)]
		value := stem
		if i >= len(stems) {
			value = fmt.Sprintf("%s-%d-%s", stem, i, strings.Repeat("Vw", i))
		}
		kind := secretscan.Credential
		if i%3 == 2 && len(value) >= secretscan.MinMaybeBytes {
			kind = secretscan.MaybeCredential
		}
		out = append(out, secretscan.Secret{Key: fmt.Sprintf("bench.adv.%d", i), Value: value, Kind: kind})
	}
	return out
}

// tokenDocument is about 16 MiB of a JSON array of the given tokens, cycled.
func tokenDocument(tokens ...string) []byte {
	const size = 16 << 20
	var b strings.Builder
	b.Grow(size + 64)
	b.WriteByte('[')
	for i := 0; b.Len() < size; i++ {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(tokens[i%len(tokens)])
	}
	b.WriteByte(']')
	return []byte(b.String())
}

func BenchmarkScanJSONAdversarial(b *testing.B) {
	shapes := []struct {
		name string
		doc  []byte
	}{
		{"percent-plus", tokenDocument(`"%+"`, `"+%"`)},
		{"tiny-plain", tokenDocument(`"a"`, `"bc"`, `"d"`)},
		{"numbers", tokenDocument(`7`, `1.5`, `2e3`, `-40`, `3E-1`)},
		{"json-escapes", tokenDocument(`"\\u00e9 \\n%41+"`, `"\\%5C"`)},
	}
	for _, shape := range shapes {
		for _, n := range []int{1, 40} {
			b.Run(fmt.Sprintf("%s/secrets=%d", shape.name, n), func(b *testing.B) {
				benchScan(b, shape.doc, adversarialSecrets(n))
			})
		}
	}
}

func benchScan(b *testing.B, doc []byte, secrets []secretscan.Secret) {
	set, err := secretscan.New(secrets)
	if err != nil {
		b.Fatalf("New: %v", err)
	}
	if got := set.NotScanned(); got != nil {
		b.Fatalf("NotScanned %q, want every secret scanned", got)
	}
	b.SetBytes(int64(len(doc)))
	samples := make([]time.Duration, 0, 64)
	for b.Loop() {
		start := time.Now()
		v := set.ScanJSON(doc)
		samples = append(samples, time.Since(start))
		if v.State != secretscan.Clean {
			b.Fatalf("verdict %+v, want clean", v)
		}
	}
	sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })
	at := func(p float64) float64 {
		return float64(samples[int(p*float64(len(samples)-1))].Nanoseconds())
	}
	b.ReportMetric(at(0.50), "p50-ns/op")
	b.ReportMetric(at(0.99), "p99-ns/op")
}
